function buildNormalizedSign(sign, overrides) {
  return omitUndefinedProperties({
    ...sign,
    ...overrides,
    clinical_finding_s_expression: normalForm(sign.clinical_finding_s_expression),
    excluding_s_expressions: sign.excluding_s_expressions && sign.excluding_s_expressions.map(normalForm),
    prompt_when_s_expression: sign.prompt_when_s_expression && normalForm(sign.prompt_when_s_expression),
    prompt_when_not_s_expression: sign.prompt_when_not_s_expression && normalForm(sign.prompt_when_not_s_expression)
  });
}
const KEYED_DEFS = keyBy(WARNING_SIGN_DEFS, "key");
function buildAdultSigns() {
  const order = WARNING_SIGN_ORDER.adult;
  const all_keys = [...order.Emergency.map((key) => ({
    key,
    priority: "Emergency",
    category: "Emergency"
  })), ...order["Very urgent"].map((key) => ({
    key,
    priority: "Very urgent",
    category: "Very urgent"
  })), ...order.Urgent.map((key) => ({
    key,
    priority: "Urgent",
    category: "Urgent"
  }))];
  return sortBy(all_keys.map(({
    key,
    priority,
    category
  }) => buildNormalizedSign(KEYED_DEFS[key], {
    priority,
    category
  })), (sign) => ORDERED_PRIORITIES.indexOf(sign.priority), (sign) => {
    const priority = sign.priority;
    return order[priority].indexOf(sign.key);
  });
}
function buildOlderChildSigns() {
  const order = WARNING_SIGN_ORDER["older child"];
  const emergency_signs = Object.entries(order.Emergency).flatMap(([subcategory, keys2]) => keys2.map((key) => buildNormalizedSign(KEYED_DEFS[key], {
    priority: "Emergency",
    category: "Emergency",
    subcategory
  })));
  const vu_signs = order["Very urgent"].map((key) => buildNormalizedSign(KEYED_DEFS[key], {
    priority: "Very urgent",
    category: "Very urgent"
  }));
  const urgent_signs = order.Urgent.map((key) => {
    const sign = buildNormalizedSign(KEYED_DEFS[key], {
      priority: "Urgent",
      category: "Urgent"
    });
    if (key === "Closed fracture") return {
      ...sign,
      description: null
    };
    return sign;
  });
  return [...emergency_signs, ...vu_signs, ...urgent_signs];
}
const WARNING_SIGNS = {
  adult: buildAdultSigns(),
  "older child": buildOlderChildSigns(),
  "younger child": []
};
